begin;
create type public.dj_set_status as enum('SCHEDULED','ACTIVE','COMPLETED','CANCELLED');
create type public.set_track_source as enum('MANUAL','AUDIO_RECOGNITION','DJ_INTEGRATION');
create table public.dj_sets(id uuid primary key default gen_random_uuid(),dj_profile_id uuid not null references public.dj_profiles(id) on delete cascade,name text,venue_name text not null,town_area text,started_at timestamptz not null default now(),ended_at timestamptz,duration_seconds integer, status public.dj_set_status not null default 'ACTIVE',is_private boolean not null default false,external_source text,external_reference text,metadata jsonb not null default '{}',created_at timestamptz not null default now());
create unique index one_active_dj_set on public.dj_sets(dj_profile_id) where status='ACTIVE';
create table public.dj_set_tracks(id uuid primary key default gen_random_uuid(),set_id uuid not null references public.dj_sets(id) on delete cascade,song_id uuid not null references public.songs(id) on delete restrict,campaign_id uuid references public.campaigns(id) on delete set null,logged_at timestamptz not null default now(),source_method public.set_track_source not null default 'MANUAL',verification_status public.verification_status not null default 'PENDING',qualification_status public.qualification_status not null default 'PENDING',play_event_id uuid references public.play_events(id) on delete set null,created_at timestamptz not null default now());
create table public.campaign_track_access_events(id bigint generated always as identity primary key,dj_profile_id uuid not null references public.dj_profiles(id) on delete cascade,campaign_id uuid not null references public.campaigns(id) on delete cascade,access_type text not null check(access_type in('PREVIEW','DOWNLOAD')),created_at timestamptz not null default now());
alter table public.dj_sets enable row level security;alter table public.dj_set_tracks enable row level security;alter table public.campaign_track_access_events enable row level security;
create policy dj_sets_self_all on public.dj_sets for all to authenticated using(exists(select 1 from public.dj_profiles d where d.id=dj_profile_id and d.profile_id=public.current_profile_id())) with check(exists(select 1 from public.dj_profiles d where d.id=dj_profile_id and d.profile_id=public.current_profile_id()));
create policy dj_tracks_self_all on public.dj_set_tracks for all to authenticated using(exists(select 1 from public.dj_sets s join public.dj_profiles d on d.id=s.dj_profile_id where s.id=set_id and d.profile_id=public.current_profile_id())) with check(exists(select 1 from public.dj_sets s join public.dj_profiles d on d.id=s.dj_profile_id where s.id=set_id and d.profile_id=public.current_profile_id()));
create policy track_access_self on public.campaign_track_access_events for select to authenticated using(exists(select 1 from public.dj_profiles d where d.id=dj_profile_id and d.profile_id=public.current_profile_id()));
grant select,insert,update on public.dj_sets to authenticated;grant select,insert on public.dj_set_tracks to authenticated;grant select on public.campaign_track_access_events to authenticated;
create function public.dj_campaign_decision(p_campaign_id uuid,p_accept boolean)returns uuid language plpgsql security definer set search_path='' as $$declare dj uuid;part uuid;begin select id into dj from public.dj_profiles where profile_id=public.current_profile_id();if dj is null then raise exception'DJ_NOT_AUTHORIZED';end if;if not exists(select 1 from public.campaigns c join public.campaign_participant_types t on t.campaign_id=c.id where c.id=p_campaign_id and c.status='ACTIVE' and t.participant_type='DJ' and current_date between c.start_date and c.end_date)then raise exception'CAMPAIGN_NOT_ELIGIBLE';end if;insert into public.campaign_participations(campaign_id,participant_type,dj_profile_id,status,accepted_at,rejected_at)values(p_campaign_id,'DJ',dj,case when p_accept then'ACCEPTED'else'REJECTED'end,case when p_accept then now()end,case when not p_accept then now()end)on conflict(campaign_id,dj_profile_id,matatu_id)do update set status=excluded.status,accepted_at=excluded.accepted_at,rejected_at=excluded.rejected_at returning id into part;return part;end$$;
create function public.log_manual_set_track(p_set_id uuid,p_campaign_id uuid)returns uuid language plpgsql security definer set search_path='' as $$declare dj uuid;song uuid;track uuid;begin select d.id into dj from public.dj_profiles d join public.dj_sets s on s.dj_profile_id=d.id where s.id=p_set_id and s.status='ACTIVE' and d.profile_id=public.current_profile_id();if dj is null then raise exception'SET_NOT_AUTHORIZED';end if;select c.song_id into song from public.campaigns c join public.campaign_participations p on p.campaign_id=c.id where c.id=p_campaign_id and p.dj_profile_id=dj and p.status in('ACCEPTED','ACTIVE')and c.status='ACTIVE';if song is null then raise exception'CAMPAIGN_NOT_ACCEPTED';end if;if exists(select 1 from public.dj_set_tracks where set_id=p_set_id and song_id=song and logged_at>now()-interval'5 minutes')then raise exception'REPEATED_TOO_SOON';end if;insert into public.dj_set_tracks(set_id,song_id,campaign_id,source_method,verification_status,qualification_status)values(p_set_id,song,p_campaign_id,'MANUAL','PENDING','PENDING')returning id into track;return track;end$$;
grant execute on function public.dj_campaign_decision(uuid,boolean),public.log_manual_set_track(uuid,uuid)to authenticated;
commit;
